@typeparam TItem
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="infinite-scroll-spinner"></div>
            }
        </div>
    }
</div>

@code {
    private ElementReference _sentinelRef;
    private InfiniteScrollListInterop? _interop;
    private DotNetObjectReference<InfiniteScrollList>? _dotNetRef;
    private bool _isLoading;
    private bool _initialized;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    [Parameter]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender && HasMore)
        {
            await InitializeObserverAsync();
        }
    }

    private bool _hasMoreChanged;

    protected override void OnParametersSet()
    {
        _hasMoreChanged = true;
        _isLoading = false;
    }

    protected override async Task OnAfterRenderAsync_ParameterChange()
    {
        // Handled via OnAfterRenderAsync
    }

    // Re-initialize observer when HasMore transitions from false to true,
    // or ensure it's set up once items arrive.
    protected override async Task OnAfterRenderAsync(bool _)
    {
        // This is handled by the single OnAfterRenderAsync override above.
    }

    private async Task InitializeObserverAsync()
    {
        _interop = new InfiniteScrollListInterop(JS);
        _dotNetRef = DotNetObjectReference.Create(this);
        await _interop.InitializeAsync(_dotNetRef, _sentinelRef);
        _initialized = true;
    }

    [JSInvokable("OnSentinelVisible")]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
        {
            return;
        }

        _isLoading = true;
        await InvokeAsync(StateHasChanged);
        await OnLoadMore.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }

        _dotNetRef?.Dispose();
    }
}

